def get_semester_courses(sem_number: int):
    """Returns verified curriculum courses for a given semester."""
    return [c for c in COURSES if c["semester"] == sem_number]

def validate_prerequisites(completed_courses: list, target_course_code: str):
    """Validates student qualification eligibility against course prerequisite trees."""
    target = next((c for c in COURSES if c["code"] == target_course_code), None)
    if not target: return False, "Course code not found in institutional catalog"
    for prereq in target["prerequisites"]:
        if prereq not in completed_courses:
            return False, f"Missing mandatory prerequisite: {prereq}"
    return True, "Eligible for registration"
